lemma hasSubgaussianMGF_mono_param {Ω : Type*} [MeasurableSpace Ω] {X : Ω → ℝ}
    {μ : Measure Ω}
    {c d : ℝ≥0} (h : HasSubgaussianMGF X c μ) (hcd : (c : ℝ) ≤ d) :
    HasSubgaussianMGF X d μ where
  integrable_exp_mul t

lemma randomQuadraticForm_aemeasurable {μ : Measure Ω} {n : ℕ}
    (A : Matrix (Fin n) (Fin n) ℝ) {X : Fin n → Ω → ℝ}
    (hX_meas : ∀ i, AEMeasurable (X i) μ) :
    AEMeasurable (randomQuadraticForm A X) μ

lemma randomQuadraticForm_mem_Icc_of_ae_coord_bound {μ : Measure Ω} {n : ℕ}
    (A : Matrix (Fin n) (Fin n) ℝ) {X : Fin n → Ω → ℝ} {K : ℝ}
    (hK : 0 ≤ K) (hX_bound : ∀ i, ∀ᵐ ω ∂μ, |X i ω| ≤ K) :
    ∀ᵐ ω ∂μ, randomQuadraticForm A X ω ∈
      Set.Icc (-(K ^ 2 * entrywiseL1Norm A)) (K ^ 2 * entrywiseL1Norm A)

lemma bounded_hansonWright_cgf_constant_le {n : ℕ}
    (A : Matrix (Fin n) (Fin n) ℝ) {K C : ℝ}
    (hC_bound : 2 * entrywiseL1Norm A ^ 2 ≤ C * frobeniusNorm A ^ 2) (l : ℝ) :
    2 * (K ^ 2 * entrywiseL1Norm A) ^ 2 * l ^ 2 ≤
      C * l ^ 2 * K ^ 4 * frobeniusNorm A ^ 2

lemma abs_inner_toEuclideanLin_le_matrixOperatorNorm_mul_norm_sq {n : ℕ}
    (A : Matrix (Fin n) (Fin n) ℝ) (x : EuclideanSpace ℝ (Fin n)) :
    |inner ℝ (A.toEuclideanLin x) x| ≤ matrixOperatorNorm A * ‖x‖ ^ 2

lemma MatrixBernsteinIndependent.neg {n N : ℕ}
    {X : Fin N → Ω → Matrix (Fin n) (Fin n) ℝ} {μ : Measure Ω}
    (hX : MatrixBernsteinIndependent X μ) :
    MatrixBernsteinIndependent (fun i ω => -X i ω) μ

lemma matrixBernsteinPiFamily_apply {n N : ℕ}
    (i : Fin N) (p : Fin N → Matrix (Fin n) (Fin n) ℝ) :
    matrixBernsteinPiFamily i p = p i
